<?php
declare(strict_types=1);require_once dirname(__DIR__,2).'/config/database.php';require_once dirname(__DIR__,2).'/includes/auth.php';requireAdmin();$errors=[];$notice='';$edit=null;if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){if(!verifyCsrfToken())$errors[]='Permintaan tidak valid.';else{$a=$_POST['action']??'';$id=(int)($_POST['jenis_surat_id']??0);if($a==='delete'&&$id){$s=$pdo->prepare('SELECT COUNT(*) FROM arsip WHERE jenis_surat_id=:id');$s->execute(['id'=>$id]);if((int)$s->fetchColumn())$errors[]='Jenis surat masih digunakan arsip dan tidak dapat dihapus.';else{$pdo->prepare('DELETE FROM jenis_surat WHERE jenis_surat_id=:id')->execute(['id'=>$id]);logActivity($pdo,(int)$_SESSION['user_id'],'DELETE');$notice='Jenis surat berhasil dihapus.';}}if(in_array($a,['create','update'],true)){$v=['nama_jenis'=>trim((string)($_POST['nama_jenis']??'')),'keterangan'=>trim((string)($_POST['keterangan']??''))?:null];if($v['nama_jenis']==='')$errors[]='Nama jenis surat wajib diisi.';$s=$pdo->prepare('SELECT jenis_surat_id FROM jenis_surat WHERE nama_jenis=:nama AND jenis_surat_id!=:id');$s->execute(['nama'=>$v['nama_jenis'],'id'=>$id]);if($s->fetch())$errors[]='Nama jenis surat sudah digunakan.';if(!$errors&&$a==='create'){$pdo->prepare('INSERT INTO jenis_surat(nama_jenis,keterangan) VALUES(:nama_jenis,:keterangan)')->execute($v);logActivity($pdo,(int)$_SESSION['user_id'],'CREATE');$notice='Jenis surat berhasil ditambahkan.';}if(!$errors&&$a==='update'&&$id){$pdo->prepare('UPDATE jenis_surat SET nama_jenis=:nama_jenis,keterangan=:keterangan WHERE jenis_surat_id=:id')->execute($v+['id'=>$id]);logActivity($pdo,(int)$_SESSION['user_id'],'UPDATE');$notice='Jenis surat berhasil diperbarui.';}}}}if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM jenis_surat WHERE jenis_surat_id=:id');$s->execute(['id'=>(int)$_GET['edit']]);$edit=$s->fetch()?:null;}$q=trim((string)($_GET['q']??''));$s=$pdo->prepare('SELECT j.*,(SELECT COUNT(*) FROM arsip a WHERE a.jenis_surat_id=j.jenis_surat_id) archive_count FROM jenis_surat j WHERE j.nama_jenis LIKE :q ORDER BY j.nama_jenis');$s->execute(['q'=>"%$q%"]);$items=$s->fetchAll();?>
