n" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="action" value="<?=$edit?'update':'create'?>"><?php if($edit):?><input type="hidden" name="jenis_surat_id" value="<?=(int)$edit['jenis_surat_id']?>"><?php endif;?><label>Nama Jenis Surat<input name="nama_jenis" required maxlength="100" value="<?=e($edit['nama_jenis']??'')?>"></label><label>Keterangan<textarea name="keterangan" maxlength="255"><?=e($edit['keterangan']??'')?></textarea></label><div><button class="primary-button">Simpan</button></div></form></section><section class="panel user-list"><h2>Daftar Jenis Surat</h2><form class="filter-form"><input name="q" value="<?=e($q)?>" placeholder="Cari jenis surat"><button>Cari</button></form><div class="table-wrap"><table><thead><tr><th>Nama</th><th>Keterangan</th><th>Arsip</th><th>Aksi</th></tr></thead><tbody><?php foreach($items as $x):?><tr><td><?=e($x['nama_jenis'])?></td><td><?=e($x['keterangan']??'-')?></td><td><?=(int)$x['archive_count']?></td><td><a href="jenis-surat.php?edit=<?=(int)$x['jenis_surat_id']?>">Edit</a><form method="post" class="inline-form"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="jenis_surat_id" value="<?=(int)$x['jenis_surat_id']?>"><button>Hapus</button></form></td></tr><?php endforeach;?></tbody></table></div></section></main></div></body></html>